// Generates src/api/schema.d.ts from ../api/openapi.draft.json (A5).
//   node scripts/api-schema.mjs           write the file
//   node scripts/api-schema.mjs --check   fail if the committed file has drifted
// The generated file is never hand-edited; regenerate after each contract change.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const source = new URL('../../api/openapi.draft.json', import.meta.url);
const target = new URL('../src/api/schema.d.ts', import.meta.url);
const check = process.argv.includes('--check');

const ast = await openapiTS(JSON.parse(await readFile(source, 'utf8')), {
  // Required-but-defaulted fields stay required in responses.
  defaultNonNullable: true,
});
const header =
  '// Generated by `npm run api:gen` from api/openapi.draft.json. Do not edit.\n' +
  '// `npm run api:check` fails when this file drifts from the contract.\n\n';
const generated = header + astToString(ast);

if (check) {
  let committed = '';
  try {
    committed = await readFile(target, 'utf8');
  } catch {
    // Missing counts as drift.
  }
  if (committed !== generated) {
    console.error(
      `${fileURLToPath(target)} is out of date with api/openapi.draft.json. Run \`npm run api:gen\` and commit the result.`,
    );
    process.exit(1);
  }
  console.log('api:check: src/api/schema.d.ts matches api/openapi.draft.json');
} else {
  await writeFile(target, generated);
  console.log(`api:gen: wrote ${fileURLToPath(target)}`);
}
